//! Parity of the models of phase 7b with BoTorch: `SingleTaskMultiFidelityGP`,
//! `MixedSingleTaskGP` and the MAP SAAS models (`get_map_saas_model`,
//! `AdditiveMapSaasSingleTaskGP`, `EnsembleMapSaasSingleTaskGP`), from the
//! fixtures in `tests/fixtures/7b_models/*.json` (generated by
//! `scripts/generate_fixtures.py --phase 7b-models`).
//!
//! Every fixture describes the model's covariance module as a JSON kernel
//! spec (see `tests/common/kernel_spec.rs`), its mean and likelihood modules,
//! the batch shape of an ensemble and the fixed SAAS taus of every element;
//! this test builds the same `BatchedMultiOutputGP` and compares with
//! BoTorch's
//!
//! * parameter names and shapes, optimizer bounds (exact) and default raw
//!   parameters (exact);
//! * MLL values of every element (1e-9, relative) and gradients (1e-8,
//!   relative to the largest component) at the default and at random raw
//!   parameters, and the prior kernel matrices (1e-9);
//! * `q = 1` posteriors of every element and output (with and without
//!   observation noise) and the gradients of their sums with respect to the
//!   inputs; joint `q = 3` posteriors and the gradient of a weighted sum of
//!   their means and covariances;
//! * fits from the default parameters (single-output, unbatched models)
//!   against BoTorch's outcomes on the model and 16 twins, as in
//!   `kernels_6a_parity.rs`; likelihoods on which BoTorch's own fits rarely
//!   reach its best outcome (fewer than a quarter of them within 1e-4) are
//!   compared statistically like chaotic ones.
//!
//! Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;

use botorch_core::models::{ConstantMeanSpec, GaussianLikelihoodSpec};
use botorch_core::{
    fit_gpytorch_mll, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, FitOptions, Matrix,
    OutcomeTransformChoice, Vector,
};
use common::kernel_spec::{constraint_of, flatten_value, node, num, prior_of};
use common::{fixture_dir, matrix, Report};
use serde::Deserialize;
use serde_json::Value;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const FIT_TOL: f64 = 1e-6;
const FIT_CLUSTER: f64 = 1e-4;
const CHAOTIC_RANGE: f64 = 1e-3;

#[derive(Deserialize)]
struct Mll {
    value: Vec<f64>,
    grad: Vec<f64>,
}

#[derive(Deserialize)]
struct PosteriorFixture {
    x: Vec<Vec<f64>>,
    mean: Vec<Vec<f64>>,
    variance: Vec<Vec<f64>>,
    variance_noisy: Vec<Vec<f64>>,
    dmean_dx: Vec<Vec<f64>>,
    dvariance_dx: Vec<Vec<f64>>,
    joint_x: Vec<Vec<f64>>,
    joint_mean: Vec<Vec<f64>>,
    joint_covariance: Vec<Vec<Vec<f64>>>,
    joint_covariance_noisy: Vec<Vec<Vec<f64>>>,
    weights_mean: Vec<Vec<f64>>,
    weights_cov: Vec<Vec<Vec<f64>>>,
    djoint_dx: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct Fit {
    loss: f64,
    iterations: usize,
    attempts: usize,
    twin_train_x: Vec<Vec<Vec<f64>>>,
    twin_losses: Vec<f64>,
    twin_attempts: Vec<usize>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    spec: Value,
    batch: Vec<usize>,
    mean: Option<Value>,
    likelihood: Option<Value>,
    saas_taus: Option<Vec<Vec<f64>>>,
    m: usize,
    fixed_noise: bool,
    standardize: bool,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    train_yvar: Option<Vec<Vec<f64>>>,
    param_names: Vec<(String, Vec<usize>)>,
    bounds: Vec<(Value, Value)>,
    default_raw: Vec<f64>,
    default_mll: Mll,
    raw: Vec<f64>,
    mll: Mll,
    k_train: Value,
    posterior: PosteriorFixture,
    fit: Option<Fit>,
    botorch_noise: Option<f64>,
}

fn load() -> Vec<Case> {
    let dir: PathBuf = fixture_dir().join("7b_models");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no 7b_models fixtures");
    paths
        .iter()
        .map(|p| {
            let text = std::fs::read_to_string(p).unwrap();
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
        })
        .collect()
}

/// The model of a case (an ensemble repeats the training data for every
/// batch element), with the fixed SAAS taus of every element.
fn build(c: &Case, train_x: &[Vec<f64>]) -> BatchedMultiOutputGP {
    let nb: usize = c.batch.iter().product();
    let likelihood = c.likelihood.as_ref().map(|l| GaussianLikelihoodSpec {
        noise_prior: Some(prior_of(&l["prior"]["__prior__"])),
        noise_constraint: constraint_of(&l["constraint"]["__constraint__"]),
    });
    let mean_module = c.mean.as_ref().map(|mm| ConstantMeanSpec {
        prior: Some(prior_of(&mm["prior"]["__prior__"])),
        constraint: Some(constraint_of(&mm["constraint"]["__constraint__"])),
    });
    let options = BatchedMultiOutputGPOptions {
        train_yvar: c
            .train_yvar
            .as_ref()
            .filter(|_| c.fixed_noise)
            .map(|v| vec![matrix(v); nb]),
        outcome_transform: if c.standardize {
            OutcomeTransformChoice::Default
        } else {
            OutcomeTransformChoice::None
        },
        covar_tree: Some(node(&c.spec)),
        likelihood,
        mean_module,
        ..Default::default()
    };
    let mut gp = BatchedMultiOutputGP::new(
        vec![matrix(train_x); nb],
        vec![matrix(&c.train_y); nb],
        c.batch.clone(),
        options,
    )
    .unwrap();
    if let Some(taus) = &c.saas_taus {
        gp.set_saas_taus(taus).unwrap();
    }
    gp
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-300);
    a.iter()
        .zip(e)
        .map(|(x, y)| (x - y).abs() / scale)
        .fold(0.0, f64::max)
}

fn check_posteriors(report: &mut Report, name: &str, gp: &BatchedMultiOutputGP, c: &Case) {
    let pf = &c.posterior;
    let nb = gp.batch_size();
    let m = c.m;
    let d = pf.x[0].len();
    let n_el = nb * m;
    let (mut mean, mut var, mut var_noisy) = (
        vec![Vec::new(); n_el],
        vec![Vec::new(); n_el],
        vec![Vec::new(); n_el],
    );
    let mut dmean = vec![0.0; pf.x.len() * d];
    let mut dvar = vec![0.0; pf.x.len() * d];
    for (i, x) in pf.x.iter().enumerate() {
        for b in 0..nb {
            for t in 0..m {
                let e = b * m + t;
                let g = gp.model(b, t);
                let (mu, v, dm, dv) = g.posterior_q1_with_grad(x).unwrap();
                mean[e].push(mu);
                var[e].push(v);
                var_noisy[e].push(v + g.observation_noise());
                for j in 0..d {
                    dmean[i * d + j] += dm[j];
                    dvar[i * d + j] += dv[j];
                }
            }
        }
    }
    let flat = |v: &[Vec<f64>]| v.iter().flatten().copied().collect::<Vec<f64>>();
    report.check_slices(
        name,
        "q=1 posterior mean",
        &flat(&mean),
        &flat(&pf.mean),
        VALUE_TOL,
    );
    report.check_slices(
        name,
        "q=1 posterior variance",
        &flat(&var),
        &flat(&pf.variance),
        VALUE_TOL,
    );
    report.check_slices(
        name,
        "q=1 noisy posterior variance",
        &flat(&var_noisy),
        &flat(&pf.variance_noisy),
        VALUE_TOL,
    );
    report.check(
        name,
        "q=1 d mean / dx",
        grad_err(&dmean, &flat(&pf.dmean_dx)),
        GRAD_TOL,
    );
    report.check(
        name,
        "q=1 d variance / dx",
        grad_err(&dvar, &flat(&pf.dvariance_dx)),
        GRAD_TOL,
    );

    let xj = matrix(&pf.joint_x);
    let q = xj.nrows();
    let mut grad = Matrix::zeros(q, d);
    for b in 0..nb {
        for t in 0..m {
            let e = b * m + t;
            let g = gp.model(b, t);
            let post = g.posterior(&xj, false).unwrap();
            let noisy = g.posterior(&xj, true).unwrap();
            report.check_slices(
                name,
                "joint posterior mean",
                post.mean.as_slice(),
                &pf.joint_mean[e],
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint posterior covariance",
                &common::matrix_rows(&post.covariance),
                &flat(&pf.joint_covariance[e]),
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint noisy posterior covariance",
                &common::matrix_rows(&noisy.covariance),
                &flat(&pf.joint_covariance_noisy[e]),
                VALUE_TOL,
            );
            let wm = Vector::from_vec(pf.weights_mean[e].clone());
            let wc = matrix(&pf.weights_cov[e]);
            grad += g.joint_posterior_vjp(&xj, 0..q, &wm, &wc).unwrap();
        }
    }
    report.check(
        name,
        "joint d (weighted sum) / dx",
        grad_err(&common::matrix_rows(&grad), &flat(&pf.djoint_dx)),
        GRAD_TOL,
    );
}

fn check_fit(report: &mut Report, name: &str, c: &Case, f: &Fit) {
    let mut fitted = build(c, &c.train_x);
    fitted.set_raw_parameters(&c.default_raw).unwrap();
    let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
    let bt: Vec<f64> = std::iter::once((f.loss, f.attempts))
        .chain(
            f.twin_losses
                .iter()
                .copied()
                .zip(f.twin_attempts.iter().copied()),
        )
        .filter(|&(_, a)| a == 1)
        .map(|(l, _)| l)
        .collect();
    let own_attempts = r.results[0].attempts;
    let rs: Vec<f64> = std::iter::once((r.loss, own_attempts))
        .chain(f.twin_train_x.iter().map(|x| {
            let mut twin = build(c, x);
            twin.set_raw_parameters(&c.default_raw).unwrap();
            let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
            (t.loss, t.results[0].attempts)
        }))
        .filter(|&(_, a)| a == 1)
        .map(|(l, _)| l)
        .collect();
    let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
    let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
    let spread = bt
        .iter()
        .copied()
        .filter(|&l| l <= bt_best + FIT_CLUSTER)
        .fold(bt_best, f64::max)
        - bt_best;
    let tol = FIT_TOL.max(10.0 * spread);
    // A multimodal likelihood: BoTorch itself rarely reaches its best
    // outcome (fewer than a quarter of its fits end within FIT_CLUSTER of it;
    // measured: `mixed_last`, 1 of 17), compared statistically like chaotic
    // likelihoods.
    let at_best = bt.iter().filter(|&&l| l <= bt_best + FIT_CLUSTER).count();
    if bt_worst - bt_best > CHAOTIC_RANGE || 4 * at_best < bt.len() {
        common::compare_chaotic_fits(report, name, "fit", &bt, &rs, FIT_TOL);
    } else {
        report.check(
            name,
            "fit: best loss above BoTorch's best (scaled)",
            (rs_best - bt_best).max(0.0) / tol,
            1.0,
        );
        if own_attempts == 1 {
            report.check(
                name,
                "fit: loss above BoTorch's worst (scaled)",
                (r.loss - bt_worst).max(0.0) / tol,
                1.0,
            );
        }
    }
    println!(
        "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
         attempts {own_attempts} (BoTorch {}), first-attempt outcomes: BoTorch \
         [{bt_best:+.10}, {bt_worst:+.10}] ({} of {}), botorch_rs best {rs_best:+.10} ({} of {})",
        r.loss,
        f.loss,
        r.results[0].iterations,
        f.iterations,
        f.attempts,
        bt.len(),
        f.twin_losses.len() + 1,
        rs.len(),
        f.twin_losses.len() + 1
    );
}

#[test]
fn models_7b_match_botorch() {
    let mut report = Report::default();
    for c in load() {
        let name = c.name.as_str();
        let mut gp = build(&c, &c.train_x);
        assert_eq!(
            gp.parameter_shapes(),
            c.param_names,
            "{name}: parameter names and shapes"
        );
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|(a, b)| (num(a), num(b))).collect();
        let bounds_ok = gp
            .raw_parameter_bounds()
            .iter()
            .zip(&bounds)
            .all(|(a, b)| a.0 == b.0 && a.1 == b.1);
        report.check(name, "bounds (exact)", f64::from(u8::from(!bounds_ok)), 0.0);
        let init = gp.raw_parameters();
        let init_err = init
            .iter()
            .zip(&c.default_raw)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0, f64::max);
        report.check(name, "default raw parameters", init_err, 0.0);
        let (v, g) = gp.mll_values_and_grad(&c.default_raw).unwrap();
        report.check_slices(name, "default MLL", &v, &c.default_mll.value, VALUE_TOL);
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );
        gp.set_raw_parameters(&c.raw).unwrap();
        let (v, g) = gp.mll_values_and_grad(&c.raw).unwrap();
        report.check_slices(name, "MLL", &v, &c.mll.value, VALUE_TOL);
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        if let Some(noise) = c.botorch_noise {
            println!("{name:26} BoTorch's MLL change by the fixed sq_dist diagonal: {noise:.2e}");
        }
        let k_expected = flatten_value(&c.k_train);
        let mut k_actual = Vec::new();
        for el in gp.models() {
            let covar = el.covar().unwrap();
            let p = covar.prepare(el.transformed_train_inputs()).unwrap();
            k_actual.extend(common::matrix_rows(&covar.symmetric(&p)));
        }
        report.check_slices(name, "kernel matrix", &k_actual, &k_expected, VALUE_TOL);
        check_posteriors(&mut report, name, &gp, &c);
        if let Some(f) = &c.fit {
            check_fit(&mut report, name, &c, f);
        }
    }
    report.finish("7b models: multi-fidelity, mixed and MAP SAAS models");
}
